SELECT COUNT(*)
FROM ADMIN_TRANSLATION
WHERE source_type = #{sourceType}
  AND source_idx = #{sourceIdx}
  AND field_name = #{fieldName}
  AND source_lang = #{sourceLang}
  AND target_lang = #{targetLang}
  AND is_primary = 1
  AND is_deleted = 0

mapper.update:
UPDATE ADMIN_TRANSLATION
SET is_primary = 0,
    updated_by = #{updatedBy},
    updated_at = CURRENT_TIMESTAMP
WHERE source_type = #{sourceType}
  AND source_idx = #{sourceIdx}
  AND field_name = #{fieldName}
  AND source_lang = #{sourceLang}
  AND target_lang = #{targetLang}
  AND is_deleted = 0

      AND translation_idx != #{excludeTranslationIdx}

mapper.select:
SELECT IFNULL(MAX(version_no), 0)
FROM ADMIN_TRANSLATION_REVISION
WHERE translation_idx = #{translationIdx}
